<template><nav class="editor-tabs"><button v-for="tab in tabs" :key="tab.id" :class="{ active: tab.id === activeId }" @click="$emit('select', tab.id)" @dblclick="rename(tab)"><span class="tab-icon">{{ tab.readOnly ? '◌' : '▦' }}</span><span class="tab-name">{{ tab.name }}</span><i @click.stop="$emit('close', tab.id)">×</i></button></nav></template>
<script setup lang="ts">
defineProps<{ tabs: any[]; activeId?: number }>(); const emit = defineEmits(['select', 'close', 'rename'])
function rename(tab: any) { emit('rename', `template-${tab.id}`, tab.name) }
</script>
<style scoped>.editor-tabs{display:flex;background:var(--surface-raised);border-bottom:1px solid var(--border);overflow-x:auto;overflow-y:hidden}.editor-tabs button{display:flex;flex:0 0 auto;align-items:center;gap:6px;min-width:130px;width:max-content;border:0;border-right:1px solid var(--border);background:transparent;color:var(--muted);padding:9px 10px;text-align:left;white-space:nowrap;cursor:pointer;font:12px var(--font)}.editor-tabs button.active{color:var(--text);background:var(--surface);border-top:2px solid var(--accent);padding-top:7px}.tab-name{white-space:nowrap}.editor-tabs i{margin-left:5px;font-style:normal;color:var(--muted);font-size:15px}</style>
